            /* Avoid issue of https://github.com/uclouvain/openjpeg/issues/1533 */
            opj_event_msg(p_manager, EVT_ERROR, "Stream too short\n");
            return OPJ_FALSE;
        }

if (l_tcp->m_nb_tile_parts) {
